DELIMITER $$

--
-- Create procedure `sp_update_proyecto`
--
CREATE

PROCEDURE sp_update_proyecto (IN p_id int,
IN p_nombre varchar(255),
IN p_descripcion text,
IN p_fecha_inicio date,
IN p_fecha_fin date,
IN p_presupuesto decimal(15, 2),
IN p_estado boolean)
BEGIN
  UPDATE proyectos
  SET nombre = p_nombre,
      descripcion = p_descripcion,
      fecha_inicio = p_fecha_inicio,
      fecha_fin = p_fecha_fin,
      presupuesto = p_presupuesto,
      estado = p_estado
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_read_proyectos_for_dropdown`
--
CREATE

PROCEDURE sp_read_proyectos_for_dropdown ()
BEGIN
  SELECT
    id,
    nombre
  FROM proyectos
  WHERE estado = TRUE
  ORDER BY nombre ASC;
END
$$

--
-- Create procedure `sp_read_proyecto_by_id`
--
CREATE

PROCEDURE sp_read_proyecto_by_id (IN p_id int)
BEGIN
  SELECT
    *
  FROM proyectos
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_read_all_proyectos`
--
CREATE

PROCEDURE sp_read_all_proyectos (IN p_codigo varchar(20),
IN p_nombre varchar(255))
BEGIN
  SELECT
    *
  FROM proyectos
  WHERE (p_codigo IS NULL
  OR p_codigo = ''
  OR codigo LIKE CONCAT('%', p_codigo, '%'))
  AND (p_nombre IS NULL
  OR p_nombre = ''
  OR nombre LIKE CONCAT('%', p_nombre, '%'));
END
$$

--
-- Create procedure `sp_delete_proyecto`
--
CREATE

PROCEDURE sp_delete_proyecto (IN p_id int)
BEGIN
  UPDATE proyectos
  SET estado = FALSE
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_create_proyecto`
