--
-- Create procedure `sp_update_sub_proyecto`
--
CREATE

PROCEDURE sp_update_sub_proyecto (IN p_id int,
IN p_id_proyecto int,
IN p_nombre varchar(255),
IN p_descripcion text,
IN p_presupuesto decimal(15, 2),
