--
-- Create procedure `sp_read_sub_proyectos_by_proyecto_id`
--
CREATE

PROCEDURE sp_read_sub_proyectos_by_proyecto_id (IN p_id_proyecto int)
BEGIN
  SELECT
    id,
    nombre
  FROM sub_proyectos
  WHERE estado = TRUE
  AND id_proyecto = p_id_proyecto
  ORDER BY nombre ASC;
END
$$

--
-- Create procedure `sp_read_sub_proyecto_by_id`
--
CREATE

PROCEDURE sp_read_sub_proyecto_by_id (IN p_id int)
