--
-- Create procedure `sp_read_all_sub_proyectos`
--
CREATE

PROCEDURE sp_read_all_sub_proyectos (IN p_codigo varchar(20),
IN p_nombre varchar(255),
IN p_id_proyecto int)
BEGIN
  SELECT
    sp.*,
    p.nombre AS nombre_proyecto
  FROM sub_proyectos sp
    JOIN proyectos p
      ON sp.id_proyecto = p.id
  WHERE (p_codigo IS NULL
  OR p_codigo = ''
  OR sp.codigo LIKE CONCAT('%', p_codigo, '%'))
  AND (p_nombre IS NULL
  OR p_nombre = ''
  OR sp.nombre LIKE CONCAT('%', p_nombre, '%'))
  AND (p_id_proyecto IS NULL
  OR p_id_proyecto = 0
  OR sp.id_proyecto = p_id_proyecto);
END
$$

--
-- Create procedure `sp_delete_sub_proyecto`
--
CREATE

PROCEDURE sp_delete_sub_proyecto (IN p_id int)
BEGIN
  UPDATE sub_proyectos
  SET estado = FALSE
  WHERE id = p_id;
END
$$

