DELIMITER $$

--
-- Create procedure `sp_update_centro_costo`
--
CREATE

PROCEDURE sp_update_centro_costo (IN p_id int,
IN p_anio smallint,
IN p_nombre varchar(255),
IN p_descripcion text,
IN p_estado tinyint)
BEGIN
  UPDATE centros_costos
  SET anio = p_anio,
      nombre = p_nombre,
      descripcion = p_descripcion,
      estado = p_estado
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_read_centros_costos_for_dropdown_by_year`
--
CREATE

PROCEDURE sp_read_centros_costos_for_dropdown_by_year (IN p_anio int)
BEGIN
  SELECT
    id,
    nombre
  FROM centros_costos
  WHERE estado = TRUE
  AND (anio = p_anio
  OR anio IS NULL)
  ORDER BY nombre ASC;
END
$$

--
-- Create procedure `sp_read_centros_costos_for_dropdown`
--
CREATE

PROCEDURE sp_read_centros_costos_for_dropdown ()
BEGIN
  SELECT
    id,
    nombre
  FROM centros_costos
  WHERE estado = TRUE
  ORDER BY nombre ASC;
END
$$

--
-- Create procedure `sp_read_centro_costo_by_id`
--
CREATE

PROCEDURE sp_read_centro_costo_by_id (IN p_id int)
BEGIN
  SELECT
    *
  FROM centros_costos
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_read_all_centros_costos`
--
CREATE

PROCEDURE sp_read_all_centros_costos (IN p_anio smallint,
IN p_codigo varchar(20),
IN p_nombre varchar(255))
BEGIN
  SELECT
    id,
    anio,
    codigo,
    nombre,
    descripcion,
    estado
  FROM centros_costos
  WHERE
  -- Filter by year. If p_anio is NULL or 0, return all years.
  (p_anio IS NULL
  OR p_anio = 0
  OR anio = p_anio)
  -- Filter by code. If p_codigo is NULL or empty, ignore this filter.
  AND (p_codigo IS NULL
  OR p_codigo = ''
  OR codigo LIKE CONCAT('%', p_codigo, '%'))
  -- Filter by name. If p_nombre is NULL or empty, ignore this filter.
  AND (p_nombre IS NULL
  OR p_nombre = ''
  OR nombre LIKE CONCAT('%', p_nombre, '%'))
  ORDER BY anio DESC, codigo ASC;
END
$$

--
-- Create procedure `sp_delete_centro_costo`
--
CREATE

PROCEDURE sp_delete_centro_costo (IN p_id int)
BEGIN
  DELETE
    FROM centros_costos
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_create_centro_costo`
--
CREATE

PROCEDURE sp_create_centro_costo (IN p_anio smallint,
IN p_codigo varchar(20),
IN p_nombre varchar(255),
IN p_descripcion text)
BEGIN
    VALUES (p_anio, p_codigo, p_nombre, p_descripcion, 1); -- Default estado to 1 (Activo)
END
$$

