--
CREATE TABLE documentos (
  id int(11) NOT NULL AUTO_INCREMENT,
  id_tipo_documento int(11) NOT NULL,
  id_proyecto int(11) NOT NULL,
  id_sub_proyecto int(11) DEFAULT NULL,
  id_centro_costo int(11) DEFAULT NULL,
  id_auxiliar int(11) NOT NULL,
  id_usuario_registro int(11) NOT NULL,
  serie_documento varchar(10) DEFAULT NULL,
  numero_documento varchar(20) NOT NULL,
  fecha_emision date NOT NULL,
  fecha_registro timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  moneda enum ('SOLES', 'DOLARES') NOT NULL,
  tipo_cambio decimal(10, 4) NOT NULL DEFAULT 1.0000,
  subtotal decimal(15, 2) NOT NULL,
  igv decimal(15, 2) NOT NULL DEFAULT 0.00,
  total decimal(15, 2) NOT NULL,
  total_soles decimal(15, 2) NOT NULL DEFAULT 0.00,
  total_dolares decimal(15, 2) NOT NULL DEFAULT 0.00,
  glosa text DEFAULT NULL,
  observaciones text DEFAULT NULL,
  estado enum ('REGISTRADO', 'APROBADO', 'ANULADO') NOT NULL DEFAULT 'REGISTRADO',
  PRIMARY KEY (id)
)
ENGINE = INNODB,
AUTO_INCREMENT = 16,
AVG_ROW_LENGTH = 2730,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

