--
ALTER TABLE documento_detalle_distribucion
ADD CONSTRAINT fk_distribucion_detalle FOREIGN KEY (id_documento_detalle)
REFERENCES documentos_detalle (id) ON DELETE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_reporte_total_soles_por_tipo_documento_y_centro_costo`
--
CREATE

PROCEDURE sp_reporte_total_soles_por_tipo_documento_y_centro_costo (IN p_anio int, IN p_mes int, IN p_id_centro_costo int)
BEGIN
  SELECT
    td.nombre AS nombre_tipo_documento,
    SUM(dd.total_soles * (ddd.porcentaje / 100)) AS total_soles
  FROM documentos_detalle dd
    JOIN documentos d
      ON dd.id_documento = d.id
    JOIN documento_detalle_distribucion ddd
      ON dd.id = ddd.id_documento_detalle
    JOIN tipos_documento td
      ON d.id_tipo_documento = td.id
  WHERE YEAR(d.fecha_emision) = p_anio
  AND MONTH(d.fecha_emision) = p_mes
  AND ddd.id_centro_costo = p_id_centro_costo
  GROUP BY td.nombre
  ORDER BY total_soles DESC;
END
$$

--
-- Create procedure `sp_reporte_total_soles_por_mes_y_centro_costo`
--
CREATE

PROCEDURE sp_reporte_total_soles_por_mes_y_centro_costo (IN p_anio int)
BEGIN
  SELECT
    MONTH(d.fecha_emision) AS mes,
    cc.nombre AS nombre_centro_costo,
    SUM(dd.total_soles * (ddd.porcentaje / 100)) AS total_soles
  FROM documentos_detalle dd
    JOIN documentos d
      ON dd.id_documento = d.id
    JOIN documento_detalle_distribucion ddd
      ON dd.id = ddd.id_documento_detalle
    JOIN centros_costos cc
      ON ddd.id_centro_costo = cc.id
  WHERE YEAR(d.fecha_emision) = p_anio
  GROUP BY MONTH(d.fecha_emision),
           cc.nombre
  ORDER BY mes,
  nombre_centro_costo;
END
$$

--
-- Create procedure `sp_reporte_total_soles_por_mes_vs_centro_costo`
--
CREATE

PROCEDURE sp_reporte_total_soles_por_mes_vs_centro_costo (IN p_anio int, IN p_mes int)
BEGIN
  SELECT
    cc.nombre AS nombre_centro_costo,
    SUM(dd.total_soles * (ddd.porcentaje / 100)) AS total_soles
  FROM documentos_detalle dd
    JOIN documentos d
      ON dd.id_documento = d.id
    JOIN documento_detalle_distribucion ddd
      ON dd.id = ddd.id_documento_detalle
    JOIN centros_costos cc
      ON ddd.id_centro_costo = cc.id
  WHERE YEAR(d.fecha_emision) = p_anio
  AND MONTH(d.fecha_emision) = p_mes
  GROUP BY cc.nombre
  ORDER BY total_soles DESC;
END
$$

--
-- Create procedure `sp_read_documento_detalle_by_id`
--
CREATE

PROCEDURE sp_read_documento_detalle_by_id (IN p_id_documento int)
BEGIN
  SELECT
    dd.id,
    dd.id_documento,
    dd.item,
    dd.cantidad,
    dd.descripcion,
    dd.id_concepto,
    dd.precio_unitario,
    dd.precio_total,
    dd.total_soles,
    dd.total_dolares,
    (SELECT
        CASE WHEN COUNT(ddd.id) > 0 THEN CONCAT('[',
              GROUP_CONCAT(
              CONCAT('{"id_centro_costo":"', ddd.id_centro_costo, '",', '"porcentaje":"', ddd.porcentaje, '"}')
              SEPARATOR ','
              ),
              ']') ELSE NULL END
      FROM documento_detalle_distribucion ddd
      WHERE ddd.id_documento_detalle = dd.id) AS distribucion
  FROM documentos_detalle dd
  WHERE dd.id_documento = p_id_documento
  ORDER BY dd.item ASC;
END
$$

--
-- Create procedure `sp_create_documento_detalle_distribucion`
--
CREATE

PROCEDURE sp_create_documento_detalle_distribucion (IN p_id_documento_detalle int,
IN p_id_centro_costo int,
IN p_porcentaje decimal(5, 2))
BEGIN
    VALUES (
    p_id_documento_detalle, p_id_centro_costo, p_porcentaje
    );
END
$$

