--
-- Create procedure `sp_get_cuentas_contables`
--
CREATE

PROCEDURE sp_get_cuentas_contables (IN `p_Emp_cCodigo` char(3), IN `p_año` char(4))
BEGIN
  SELECT
    Pla_cCuentaContable AS value,
    CONCAT(Pla_cCuentaContable, ' - ', Pla_cNombreCuenta) AS text
  FROM cnm_plan_cta
  WHERE Emp_cCodigo = p_Emp_cCodigo
  AND Pan_cAnio = p_año
  AND Pla_cEstado = 'A'
  AND Pla_cTitulo = 'N'
  ORDER BY Pla_cCuentaContable;
