  SELECT
    *
  FROM tipos_cambio
  WHERE (p_fecha_inicio IS NULL
  OR fecha >= p_fecha_inicio)
  AND (p_fecha_fin IS NULL
  OR fecha <= p_fecha_fin)
  ORDER BY fecha DESC;
END
$$

--
-- Create procedure `sp_delete_tipo_cambio`
--
CREATE

PROCEDURE sp_delete_tipo_cambio (IN p_id int)
BEGIN
  DELETE
    FROM tipos_cambio
  WHERE id = p_id;
END
$$

--
-- Create procedure `sp_create_tipo_cambio`
--
CREATE

PROCEDURE sp_create_tipo_cambio (IN p_fecha date,
IN p_compra decimal(10, 4),
IN p_venta decimal(10, 4))
BEGIN
    VALUES (p_fecha, p_compra, p_venta);
END
$$

